#!/usr/bin/env bash
# Build Retirement Map and push it live.
#   ./deploy.sh
#
# Deploys to apps.eloquentix.com/mc/ via the radu-deploy ssh host. This repo owns all.html,
# angels.html, artist.html, indie.html (generated from src/retirement-map.html) and plan.html
# (a separate, hand-authored single-file EN|FR product — not generated by build.mjs, pushed
# as-is). homes.html (one-salary-two-homes) builds locally but isn't published — legacy.
#
# Moved 2026-11-03 from the nested /radu/mc/ path to this top-level one; the old path now
# 301-redirects here (see /etc/nginx/sites-available/apps on the server).
#
# Uses the `radu-deploy` host from ~/.ssh/config (key: id_ed25519_eloquentix),
# so it does not depend on ssh-agent state.
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
HOST="radu-deploy"
REMOTE="/var/www/apps/mc"

cd "$ROOT"

echo "▸ building pages…"
node build.mjs

PAGES=(all.html angels.html artist.html indie.html plan.html)

echo "▸ ensuring remote dir…"
ssh "$HOST" "mkdir -p $REMOTE"

echo "▸ pushing pages…"
scp "${PAGES[@]}" "$HOST:$REMOTE/"

echo "▸ fixing ownership…"
ssh "$HOST" "chown -R www-data:www-data $REMOTE"

echo "▸ verifying…"
base="https://apps.eloquentix.com/mc"
for p in "${PAGES[@]}"; do
  code=$(curl -s -o /dev/null -w "%{http_code}" "$base/$p")
  printf "  %s  %s/%s\n" "$code" "$base" "$p"
done

echo "✓ deployed."
